# Independent tests from frozen test-spec.md; no upstream helpers.
(function(){
saved_seed <- if(exists('.Random.seed',.GlobalEnv,inherits=FALSE)) get('.Random.seed',.GlobalEnv) else NULL; saved_kind<-RNGkind(); on.exit({do.call(RNGkind,as.list(saved_kind)); if(is.null(saved_seed)){if(exists('.Random.seed',.GlobalEnv,inherits=FALSE))rm('.Random.seed',envir=.GlobalEnv)} else assign('.Random.seed',saved_seed,.GlobalEnv)},add=TRUE)
library(simCoDaR)
B <- rbind(c(-1,1,0)/sqrt(2),c(-1,-1,2)/sqrt(6)); parts <- c('A','B','C')
inv <- function(z,b=B) { a<-z%*%b; a<-exp(a-apply(a,1,max)); a/rowSums(a) }
frm <- function(x) {x<-as.data.frame(x); names(x)<-parts[seq_len(ncol(x))]; x}
fwd <- function(x,b=B) log(as.matrix(x))%*%t(b)
normal_ref <- function(z,mu,s) {r<-sweep(z,2,mu); -.5*(ncol(z)*log(2*pi)+as.numeric(determinant(s,logarithm=TRUE)$modulus)+rowSums((r%*%solve(s))*r))}
t_ref <- function(z,mu,s,df=5) {r<-sweep(z,2,mu); p<-ncol(z); lgamma((df+p)/2)-lgamma(df/2)-.5*(p*log(df*pi)+as.numeric(determinant(s,logarithm=TRUE)$modulus))-(df+p)/2*log1p(rowSums((r%*%solve(s))*r)/df)}
mix_ref <- function(z,m) {a<-sapply(seq_along(m$weights),function(j) log(m$weights[j])+normal_ref(z,m$means[j,],m$covariances[[j]])); peak<-apply(a,1,max); peak+log(rowSums(exp(a-peak)))}
rows<-list(); fits<-list(); data_sets<-list()
rec <- function(id,metric,expected,actual,tol=0) {err<-if(is.numeric(actual)&&is.numeric(expected)) max(abs(actual-expected)) else if(identical(actual,expected)) 0 else Inf; ok<-is.finite(err)&&err<=tol; rows[[length(rows)+1L]]<<-data.frame(test=id,metric=metric,expected=paste(signif(expected,10),collapse=','),actual=paste(signif(actual,10),collapse=','),tolerance=tol,error=err,relative_error=if(is.numeric(expected)&&any(expected!=0)) max(abs(actual-expected)/pmax(abs(expected),1e-300)) else NA,verdict=if(ok)'PASS' else 'FAIL'); cat(id,metric,'expected=',paste(expected,collapse=','),'actual=',paste(actual,collapse=','),'tol=',tol,if(ok)'PASS' else 'FAIL','\n'); invisible(ok)}
# Boolean is numerical to preserve uniform evidence output.
yes <- function(id,metric,value) rec(id,metric,1,as.integer(isTRUE(value)))
err <- function(id,fun) {e<-tryCatch({fun(); NULL},error=function(e) conditionMessage(e)); cat('ERROR PROBE',id,if(is.null(e))'NO ERROR' else e,'\n'); yes(id,'explicit rejection',!is.null(e)); invisible(e)}
case <- function(id,fun) tryCatch(fun(),error=function(e) {cat('UNEXPECTED ERROR',id,conditionMessage(e),'\n'); yes(id,'completed',FALSE)})
fit <- function(d,model,...) fit_assay_simulator(d,names(d)[1:3],model=model,...)
h <- function(f) f$groups[[1]]$patterns[[1]]
den <- getFromNamespace('.assay_log_density','simCoDaR')
