 } else if(model=='logistic_normal') {rec(model,'sample location',0,max(abs(m$mu-colMeans(zfit))),1e-10); ridge<-m$diagnostics$regularization$added; rec(model,'sample covariance plus declared ridge',0,max(abs(m$sigma-cov(zfit)-diag(ridge,2))),1e-9); yes(model,'off diagonal retained',abs(m$sigma[1,2])>.1)} else if(model=='ilr_student_t') {
