 } else {ord<-order(m$means[,1]); rec(model,'chosen components',2,m$selected_components); for(j in 1:2) {jj<-ord[j]; rec(model,paste0('weight',j),c(.4,.6)[j],m$weights[jj],6*sqrt(.4*.6/n)); for(l in 1:2) rec(model,paste0('mean',j,l),ms[j,l],m$means[jj,l],6*sqrt(ss[[j]][l,l]/(n*c(.4,.6)[j]))); zz<-z[g==j,,drop=FALSE]; batches<-split(seq_len(nrow(zz)),rep(1:10,length.out=nrow(zz))); cv<-sapply(batches,function(ii) as.vector(cov(zz[ii,,drop=FALSE]))); se<-apply(cv,1,sd)/sqrt(10); for(l in 1:4) rec(model,paste0('covariance',j,l),ss[[j]][l],m$covariances[[jj]][l],6*se[l]+attr(m$covariances[[jj]],'regularization')$added)}; bic<- -2*m$loglik+11*log(n); rec(model,'training BIC',bic,unname(m$bic['2']),1e-8*abs(bic)); yes(model,'minimum BIC selection',as.integer(names(which.min(m$bic)))==m$selected_components); yes(model,'starts exposed',length(m$diagnostics$starts)==5); rec(model,'weight sum',1,sum(m$weights),1e-12) }
 if(model!='dirichlet') {points<-rbind(c(.4,-.3),c(1,-1),c(8,-6)); pd<-frm(inv(points,q$basis)); ref<-switch(model,logistic_normal=normal_ref(points,m$mu,m$sigma),ilr_student_t=t_ref(points,m$mu,m$sigma),ilr_mixture=mix_ref(points,m)); rec(model,'closed form density',0,max(abs(as.numeric(den(f,pd))-ref)),1e-9)}
 jac<- -log(3)/2-rowSums(log(x[1:4,])); rec(model,'common Jacobian (current simplex alias)',0,max(abs(as.numeric(den(f,d[1:4,],measure='simplex')-den(f,d[1:4,]))-jac)),1e-9); case(paste0(model,' required measure'),function() {actual<-den(f,d[1:4,],measure='simplex_coordinate'); rec(model,'required measure Jacobian',0,max(abs(as.numeric(actual-den(f,d[1:4,]))-jac)),1e-9)})
 y<-simulate_assays(f,20000,seed=switch(model,dirichlet=4201,logistic_normal=4202,ilr_student_t=4203,ilr_mixture=4204)); yes(model,'sample finite positive',all(is.finite(as.matrix(y)))&&all(as.matrix(y)>0)); rec(model,'sample closure',0,max(abs(rowSums(y)-1)),1e-10)
