 batch<-split(1:20000,rep(1:20,each=1000)); means<-sapply(batch,function(ii)colMeans(yy[ii,,drop=FALSE])); covs<-sapply(batch,function(ii)as.vector(cov(yy[ii,,drop=FALSE]))); seM<-if(model %in% c('dirichlet','logistic_normal'))sqrt(diag(cv)/20000) else apply(means,1,sd)/sqrt(20); seC<-apply(covs,1,sd)/sqrt(20); for(j in seq_along(target)) rec(model,paste0('draw mean',j),target[j],mean(yy[,j]),6*seM[j]+if(model %in% c('dirichlet','logistic_normal'))0 else 1e-8); for(j in seq_along(cv)) rec(model,paste0('draw covariance',j),cv[j],cov(yy)[j],6*seC[j]+1e-8)
 if(model %in% c('logistic_normal','ilr_student_t')) for(j in 1:2) {prob<-c(.05,.5,.95); sq<-sqrt(m$sigma[j,j]); theoretical<-m$mu[j]+sq*if(model=='logistic_normal')qnorm(prob) else qt(prob,5); density<-if(model=='logistic_normal')dnorm(qnorm(prob))/sq else dt(qt(prob,5),5)/sq; for(l in 1:3) rec(model,paste0('draw quantile',j,prob[l]),theoretical[l],unname(quantile(yy[,j],prob[l])),6*sqrt(prob[l]*(1-prob[l])/20000)/density[l]+1e-6); if(model=='ilr_student_t')rec(model,paste0('tail',j),.05,mean(yy[,j]>m$mu[j]+sq*qt(.95,5)),6*sqrt(.05*.95/20000))}
