 rescaled<-d*seq(.1,10,length.out=n); fr<-fit(rescaled,model,mixture_components=1:2); mr<-h(fr)$model; if(model=='logistic_normal') {rec(model,'rescale location',0,max(abs(mr$mu-m$mu)),1e-10); rec(model,'rescale draws',0,max(abs(as.matrix(simulate_assays(fr,40))-as.matrix(y2))),1e-10)} else rec(model,'rescale likelihood relative',0,abs(mr$loglik-m$loglik)/max(1,abs(m$loglik)),1e-6)
