case('structural groups',function(){v<-2+(1:40)/40;d<-data.frame(A=rep(v,2),B=c(rep(1,40),rep(0,40)),C=c(rep(0,40),rep(1,40)),G=rep(c('G1','G2'),each=40));for(model in names(fits)){f<-fit(d,model,group_col='G',zero_mode='structural',structural_parts=c('B','C'),mixture_components=1);y<-simulate_assays(f,10000);yes(model,'structural absences',all(y$C[y$G=='G1']==0)&&all(y$B[y$G=='G2']==0));yes(model,'structural active positivity',all(y$A>0)&&all(y$B[y$G=='G1']>0)&&all(y$C[y$G=='G2']>0));rec(model,'group probability',.5,mean(y$G=='G1'),6*sqrt(.5*.5/10000));rec(model,'support count',40,f$groups$G1$patterns[[1]]$count);conditional<-as.numeric(den(f,d,conditional_group=TRUE));default<-as.numeric(den(f,d));rec(model,'default conditional group density',0,max(abs(default-conditional)),1e-9);joint<-as.numeric(den(f,d,conditional_group=FALSE));rec(model,'joint label mass',log(.5),mean(joint-conditional),1e-9);err(paste(model,'missing density label'),function()den(f,d[parts]));dd<-d;dd$G<-'unknown';err(paste(model,'invalid density label'),function()den(f,dd));dd<-d[1,,drop=FALSE];dd$C<-1;yes(model,'impossible support -Inf',is.infinite(den(f,dd))&&den(f,dd)<0)};err('undeclared structural',function()fit(d,'logistic_normal',zero_mode='structural',structural_parts='B'));err('censoring mode',function()fit(d,'logistic_normal',zero_mode='censoring'));err('sparse structural',function()fit(d[c(1,2,41,42),],'logistic_normal',group_col='G',zero_mode='structural',structural_parts=c('B','C')));dd<-data.frame(A=c(1,0),B=c(0,1),C=c(0,0));ff<-fit(dd,'logistic_normal',zero_mode='structural',structural_parts=parts);yy<-simulate_assays(ff,100);yes('singleton','exact one',all(rowSums(yy==1)==1)&&all(rowSums(yy)==1));rec('singleton','support mass',log(.5),as.numeric(den(ff,dd))[1],1e-9)})
case('degeneracy failures and RNG',function(){for(model in names(fits)){d<-data_sets[[model]];cfg<-switch(model,dirichlet=list(dirichlet_maxit=1L),ilr_student_t=list(student_max_iter=1L),ilr_mixture=list(mixture_max_iter=1L),logistic_normal=NULL);if(!is.null(cfg)){set.seed(29);before<-.Random.seed;kind<-RNGkind();err(paste(model,'iteration exhaustion'),function()fit(d,model,control=cfg,mixture_components=2));yes(model,'RNG restored on fit error',identical(before,.Random.seed)&&identical(kind,RNGkind()));rm('.Random.seed',envir=.GlobalEnv);err(paste(model,'absent state exhaustion'),function()fit(d,model,control=cfg,mixture_components=2));yes(model,'absent state restored on error',!exists('.Random.seed',.GlobalEnv,inherits=FALSE))};err(paste(model,'identical rows'),function()fit(d[rep(1,80),],model,mixture_components=2));f<-fits[[model]];f$groups[[1]]$patterns[[1]]$model$convergence<-1L;set.seed(23);before<-.Random.seed;err(paste(model,'unconverged tamper'),function()simulate_assays(f,10));yes(model,'sampler error RNG restore',identical(before,.Random.seed));rm('.Random.seed',envir=.GlobalEnv);err(paste(model,'absent sampler error'),function()simulate_assays(f,10));yes(model,'sampler error absent restore',!exists('.Random.seed',.GlobalEnv,inherits=FALSE))};v<-seq(-1,1,length.out=80);d<-frm(inv(cbind(v,2*v))); for(model in c('logistic_normal','ilr_student_t')) {f<-tryCatch(fit(d,model),error=function(e){cat('near singular explicit rejection',model,conditionMessage(e),'\n');NULL});if(is.null(f))yes(model,'near singular clear rejection',TRUE) else {m<-h(f)$model;yes(model,'near singular transparent ridge',m$diagnostics$regularization$added>0);yes(model,'near singular finite density',all(is.finite(den(f,d))));yes(model,'near singular finite draw',all(is.finite(as.matrix(simulate_assays(f,100)))))} };d<-data_sets$ilr_student_t;d[1,]<-frm(inv(matrix(c(100,-100),1)));f<-fit(d,'ilr_student_t');yes('Student outlier','finite robust likelihood',is.finite(h(f)$model$loglik));err('mixture insufficient rows',function()fit(data_sets$ilr_mixture[1:30,],'ilr_mixture',mixture_components=10));d<-frm(inv(rbind(matrix(c(-3,0),40,2,byrow=TRUE),matrix(c(3,0),40,2,byrow=TRUE))));err('mixture repeated regimes',function()fit(d,'ilr_mixture',mixture_components=2))})
case('additional contracts',function(){
 for(model in names(fits)){d<-data_sets[[model]];f<-fits[[model]];m<-h(f)$model
  if(model=='dirichlet'){a<-m$alpha;x<-as.matrix(d[1:4,]);ref<-lgamma(sum(a))-sum(lgamma(a))+as.vector(log(x)%*%(a-1))+log(3)/2+rowSums(log(x));rec(model,'direct ILR Dir density',0,max(abs(as.numeric(den(f,d[1:4,]))-ref)),1e-9)}
  rr<-fit(d*seq(.1,10,length.out=nrow(d)),model,mixture_components=1:2);mr<-h(rr)$model;parameters<-function(m)unlist(m[intersect(names(m),c('alpha','mu','sigma','means','weights','covariances'))]);rec(model,'rescale parameters relative',0,max(abs(parameters(mr)-parameters(m))/pmax(1,abs(parameters(m)))),if(model=='logistic_normal')1e-10 else 1e-6)
  if(model=='ilr_mixture'){set.seed(337);before<-.Random.seed;invisible(fit(d,model,seed=NULL,mixture_components=1:2));yes(model,'NULL fit advances state',!identical(before,.Random.seed));yes(model,'failed starts are exposed',all(vapply(m$diagnostics$starts,function(s)s$status!='failed'||!is.null(s$reason),logical(1))))}
  yes(model,'part order',identical(names(simulate_assays(f,2)),parts));ff<-f;if(model=='dirichlet')ff$groups[[1]]$patterns[[1]]$model$alpha[]<-exp(-15) else if(model=='ilr_mixture')ff$groups[[1]]$patterns[[1]]$model$means[]<-.Machine$double.xmax else ff$groups[[1]]$patterns[[1]]$model$mu[]<-.Machine$double.xmax
  set.seed(477);before<-.Random.seed;err(paste(model,'draw time error'),function()simulate_assays(ff,50));yes(model,'draw time error seed restored',identical(before,.Random.seed));rm('.Random.seed',envir=.GlobalEnv);err(paste(model,'absent draw time error'),function()simulate_assays(ff,50));yes(model,'draw time absent restored',!exists('.Random.seed',.GlobalEnv,inherits=FALSE))
 }
})
result<-do.call(rbind,rows)
for(i in seq_len(nrow(result))) testthat::test_that(paste('independent M1',result$test[i],result$metric[i]), {testthat::expect_identical(result$verdict[i], 'PASS', info=paste('Expected',result$expected[i],'actual',result$actual[i],'tolerance',result$tolerance[i]))})

})()
